refsect1.programlisting:
node /org/freedesktop/RealtimeKit1 {
  interface org.freedesktop.RealtimeKit1 {
    methods:
      MakeThreadRealtime(in  t thread,
                         in  u priority);
      MakeThreadRealtimeWithPID(in  t process,
                                in  t thread,
                                in  u priority);
      MakeThreadHighPriority(in  t thread,
                             in  i nice_level);
      MakeThreadHighPriorityWithPID(in  t process,
                                    in  t thread,
                                    in  i nice_level);
      ResetKnown();
      ResetAll();
      Suspend();
      Resume();
      @org.freedesktop.systemd1.Privileged("true")
      Exit();
    properties:
      @org.freedesktop.DBus.Property.EmitsChangedSignal("const")
      readonly x RTTimeUSecMax = ...;
      @org.freedesktop.DBus.Property.EmitsChangedSignal("const")
      readonly i MaxRealtimePriority = ...;
      @org.freedesktop.DBus.Property.EmitsChangedSignal("const")
      readonly i MinNiceLevel = ...;
  };
  interface org.freedesktop.DBus.Peer { ... };
  interface org.freedesktop.DBus.Introspectable { ... };
  interface org.freedesktop.DBus.Properties { ... };
};
